"""Compare tables regenerated by build_dossier_v3.py with the delivered ones (no adjustment, only a report).
    python scripts/compare_dossier_tables.py --new <dir> --old <dir>   (old: handoff_memoria or the unzipped v3.3 package)
"""
import argparse
import pathlib
import numpy as np
import pandas as pd


def cmp(new, old, keys, name):
    new, old = new.copy(), old.copy()
    for d in (new, old):
        if "tag" in d:
            d["tag"] = d["tag"].fillna("")
    print(f"== {name}: rows new={len(new)} old={len(old)}; columns equal={list(new.columns) == list(old.columns)}")
    m = new.merge(old, on=keys, how="outer", suffixes=("_new", "_old"), indicator=True)
    print("   rows only in new:", int((m._merge == "left_only").sum()), "| only in old:", int((m._merge == "right_only").sum()),
          "| arms new/old:", new.arm.nunique(), old.arm.nunique())
    both = m[m._merge == "both"]
    worst = {}
    for c in [c for c in new.columns if c not in keys and c in old.columns]:
        a, b = both[c + "_new"], both[c + "_old"]
        if pd.api.types.is_numeric_dtype(a) and pd.api.types.is_numeric_dtype(b):
            d = (a - b).abs()
            worst[c] = (float(np.nanmax(d)) if d.notna().any() else 0.0, int(((a.isna()) != (b.isna())).sum()))
        else:
            worst[c] = (int((a.astype(str) != b.astype(str)).sum()), 0)
    for c, (w, nn) in worst.items():
        print(f"   {c:24s} max|diff|={w:.3g}  nan-mismatch={nn}")
    return m


def main():
    p = argparse.ArgumentParser(); p.add_argument("--new", required=True); p.add_argument("--old", required=True)
    a = p.parse_args(); new, old = pathlib.Path(a.new), pathlib.Path(a.old)
    cmp(pd.read_csv(new / "per_seed_metrics.csv"), pd.read_csv(old / "per_seed_metrics.csv"), ["exp", "arm", "fix", "tag", "seed"], "per_seed_metrics.csv")
    cmp(pd.read_csv(new / "summary_by_arm.csv"), pd.read_csv(old / "summary_by_arm.csv"), ["exp", "arm", "fix01", "tag"], "summary_by_arm.csv")
    for f, val in (("curves_eval_greedy.csv", "greedy_return"), ("curves_train_ma50.csv", "train_ma50")):
        if (old / f).exists():
            cmp(pd.read_csv(new / f), pd.read_csv(old / f), ["exp", "arm", "fix", "tag", "seed", "global_step"], f)


if __name__ == "__main__":
    main()
